// TypeScript Version: 4.1

/**
* Computes the log loss gradient with respect to the predicted value.
*
* ## Notes
*
* -   If `y` is not +1 or -1, the function returns `NaN`.
*
* @param y - true target value
* @param p - predicted value
* @returns log loss gradient
*
* @example
* var v = logGradient( 1.0, 0.782 );
* // returns ~-0.314
*
* @example
* var v = logGradient( 1.0, 0.202 );
* // returns ~-0.45
*
* @example
* var v = logGradient( 1.0, -0.999 );
* // returns ~-0.731
*
* @example
* var v = logGradient( -1.0, 0.234 );
* // returns ~0.558
*
* @example
* var v = logGradient( -1.0, 0.2 );
* // returns ~0.55
*
* @example
* var v = logGradient( 1.0, -0.9 );
* // returns ~-0.711
*/
declare function logGradient( y: number, p: number ): number;


// EXPORTS //

export = logGradient;
